pragma solidity >=0.8.0;

error BadAddr(address who, address zero);

contract DeepRevertProbe {
    uint256 public count;
    event Incremented(uint256 newCount);

    function bump() public {
        count += 1;
        emit Incremented(count);
    }

    function failDeep(uint256 mode) public returns (uint256) {
        return l1(mode);
    }

    function l1(uint256 mode) internal returns (uint256) {
        return l2(mode);
    }

    function l2(uint256 mode) internal returns (uint256) {
        return l3(mode);
    }

    function l3(uint256 mode) internal returns (uint256) {
        if (mode == 0) {
            require(false, 'deep require');
        }
        if (mode == 1) {
            revert BadAddr(msg.sender, address(0));
        }
        if (mode == 2) {
            uint256 z = 0;
            return 1 / z;
        }
        return 7;
    }
}
